changeSet.sql:
create or alter procedure [graph].[GetHop] @assets dbo.AssetBrowserImpactTable readonly, @initial bit, @hopCount int, @diagramType int, --Lineage = 1, Impact = 2 @hopType int,
@resourceId int, @isAdmin bit,
-- Only relevant below if NOT initial @ignoredRelations dbo.UidTable readonly, @direction char(1), -- (F)orward, (B)ackward @predicateUid uniqueidentifier, @leafOnly bit = 1 as begin set nocount on;
if @initial = 1 begin set @direction = null set @predicateUid = null end
drop table if exists #relationsToIgnore create table #relationsToIgnore ([Uid] uniqueidentifier) create index ix_TempRelationsToIgnore on #relationsToIgnore (Uid asc)
insert into #relationsToIgnore select * from @ignoredRelations;
-- Temporary Table Creation drop table if exists #assetIds create table #assetIds ([Uid] uniqueidentifier, ID bigint, Class int, [Key] varchar(50), [Parsed] bit) create index ix_TempAssetIds on #assetIds (ID asc)
drop table if exists #hopAssets create table #hopAssets (ID bigint, [Key] varchar(50), Direction char(1), HopNumber int) create index ix_TempHopAssets on #hopAssets (ID asc) create clustered index cix_TempHopAssets on #hopAssets ([Key] asc, HopNumber desc)
drop table if exists #links; create table #links ( RowID int identity not null, [Uid] uniqueidentifier, Direction char(1), HopNumber int, ProvidedKey varchar(50), [Key] varchar(50), ID bigint, [AssetUid] uniqueidentifier, PredicateId int, PredicateUid uniqueidentifier, [Predicate] nvarchar(250), PredicateType int, IsFocal bit default(0) PRIMARY KEY CLUSTERED ( [RowID] ASC ) ); CREATE NONCLUSTERED INDEX IX_TempLinks_Uid on #links (Uid);
drop table if exists #nodes create table #nodes ( RowID int identity not null, [Level] int, [Position] int default(1), AssetUid uniqueidentifier, AssetID bigint, [Key] varchar(50), ParentID bigint null, ParentKey varchar(50), Back varchar(25), Fore varchar(25), Icon varchar(50), AssetTypeID int, AssetTypeUid uniqueidentifier, Class int, DisplayValue nvarchar(500), Reveal int, ActionCount int, RelationCounts varchar(max), OwnerCounts varchar(max), UseAsTransformation bit null, IsLeaf bit, IsSubjectInTransformation bit null, HasAssetReadAccess bit null, [Parsed] tinyint, IsFocal bit default(0), PRIMARY KEY CLUSTERED ( [RowID] ASC ) ); create index ix_Temp_Nodes_AssetID on #nodes ([AssetID] asc); create index ix_Temp_Nodes_AssetID_IsLeaf on #nodes ([AssetID] asc, IsLeaf asc); create index ix_Temp_Nodes_AssetTypeID_IsLeaf on #nodes ([AssetTypeID] asc, IsLeaf asc);
declare @hopSalt varchar(25) = graph.Hop_GenerateSalt();
-- Load incoming assets into temporary table. insert into #assetIds select distinct A.Uid, A.ID, T.[Class], O.[Key], 0 as [Parsed] from Asset A inner join @assets O on O.Uid = A.Uid inner join AssetType T on T.ID = A.AssetTypeID;
update #assetIds set [Key] = utility.GetHash(@hopSalt + '|' + cast(ID as varchar(50))) where [Key] is null or [Key] = '';
declare @currentHopCount int = 0, @expanded bit, @revealCheckNeeded bit;
while @currentHopCount <= @hopCount begin set @expanded = case when @currentHopCount < @hopCount then 1 else 0 end set @revealCheckNeeded = case when @currentHopCount < @hopCount then 0 else 1 end set @hopSalt = graph.Hop_GenerateSalt(); -- Reset the salt.
if @currentHopCount = 0 begin if @initial = 1 begin exec graph.Hop_GetSelf @diagramType, @hopSalt, @leafOnly end else begin insert into #hopAssets select ID, [Key], @direction, 0 from #assetIds; end end else begin if @hopType = 2 begin -- IMPACT if @initial = 1 begin exec graph.Hop_GetImpact @hopSalt, @diagramType, 'B', @predicateUid, @currentHopCount, 0, @leafOnly; set @hopSalt = graph.Hop_GenerateSalt(); exec graph.Hop_GetImpact @hopSalt, @diagramType, 'F', @predicateUid, @currentHopCount, 0, @leafOnly; end else begin exec graph.Hop_GetImpact @hopSalt, @diagramType, @direction, @predicateUid, @currentHopCount, 1, @leafOnly; end end else begin -- LINEAGE if @initial = 1 begin exec graph.Hop_GetLineage @hopSalt, 'B', @currentHopCount, @revealCheckNeeded, @leafOnly; set @hopSalt = graph.Hop_GenerateSalt(); exec graph.Hop_GetLineage @hopSalt, 'F', @currentHopCount, @revealCheckNeeded, @leafOnly; end else begin exec graph.Hop_GetLineage @hopSalt, @direction, @currentHopCount, @revealCheckNeeded, @leafOnly; end end end
exec graph.Hop_GetBadgeCounts @diagramType, @expanded, @currentHopCount; -- Get count values on badges that should be attached to assets.
-- Prepare for the next loop by resetting the assets we are interested in. if @currentHopCount > 0 begin insert into #relationsToIgnore select distinct Uid from #links where Uid not in (select Uid from #relationsToIgnore) and Uid is not null end
update #assetIds set Parsed = 1 where parsed = 0; update #nodes set Parsed = 1 where parsed = 0;
set @currentHopCount = @currentHopCount + 1 end
--Now set read access permissions on assets. update #nodes set HasAssetReadAccess = 1;
update N set HasAssetReadAccess = 0 from #nodes N cross apply dbo.UserAssetPermissions(@resourceId,N.AssetTypeID) P where P.AssetID = N.AssetID and P.PermissionsBitMask & 1 = 0;
exec graph.Hop_GetResults @diagramType; -- Return to caller. end

changeSet.rollback:
