if @currentHopCount = 0 begin if @initial = 1 begin exec graph.Hop_GetSelf @diagramType, @hopSalt, @leafOnly end else begin insert into #hopAssets select ID, [Key], @direction, 0 from #assetIds; end end else begin if @hopType = 2 begin -- IMPACT if @initial = 1 begin exec graph.Hop_GetImpact @hopSalt, @diagramType, 'B', @predicateUid, @currentHopCount, 0, @leafOnly; set @hopSalt = graph.Hop_GenerateSalt(); exec graph.Hop_GetImpact @hopSalt, @diagramType, 'F', @predicateUid, @currentHopCount, 0, @leafOnly; end else begin exec graph.Hop_GetImpact @hopSalt, @diagramType, @direction, @predicateUid, @currentHopCount, 1, @leafOnly; end end else begin -- LINEAGE if @initial = 1 begin exec graph.Hop_GetLineage @hopSalt, 'B', @currentHopCount, @revealCheckNeeded, @leafOnly; set @hopSalt = graph.Hop_GenerateSalt(); exec graph.Hop_GetLineage @hopSalt, 'F', @currentHopCount, @revealCheckNeeded, @leafOnly; end else begin exec graph.Hop_GetLineage @hopSalt, @direction, @currentHopCount, @revealCheckNeeded, @leafOnly; end end end
exec graph.Hop_GetBadgeCounts @diagramType, @expanded, @currentHopCount; -- Get count values on badges that should be attached to assets.
-- Prepare for the next loop by resetting the assets we are interested in. if @currentHopCount > 0 begin insert into #relationsToIgnore select distinct Uid from #links where Uid not in (select Uid from #relationsToIgnore) and Uid is not null end
update #assetIds set Parsed = 1 where parsed = 0; update #nodes set Parsed = 1 where parsed = 0;
